#pragma once
#include "../Core/Types.h"
#include "../Features/ESP.h"
#include <string>
#include <vector>
#include <functional>

namespace KyxMarvel {

// =====================================================================
// IRenderer — abstract rendering backend
// Implementation provided by the overlay (ImGui, GDI+, Vulkan, etc.)
// This processes the ESPDrawList generated by ESP/Radar engines.
// =====================================================================

class IRenderer {
public:
    virtual ~IRenderer() = default;

    // --- Primitives ---
    virtual void DrawRect(const FVector2D& min, const FVector2D& max,
                          const FColor& color, float thickness, bool filled) = 0;

    virtual void DrawLine(const FVector2D& from, const FVector2D& to,
                          const FColor& color, float thickness) = 0;

    virtual void DrawCircle(const FVector2D& center, float radius,
                            const FColor& color, float thickness, bool filled) = 0;

    virtual void DrawText(const FVector2D& pos, const std::string& text,
                          const FColor& color, float size, bool centered) = 0;

    virtual void DrawGradientRect(const FVector2D& min, const FVector2D& max,
                                  const FColor& topColor, const FColor& bottomColor) = 0;

    virtual void DrawRoundedRect(const FVector2D& min, const FVector2D& max,
                                 const FColor& color, float thickness,
                                 float rounding, bool filled) = 0;

    // --- Screen info (overlay must provide) ---
    virtual double GetScreenWidth() const = 0;
    virtual double GetScreenHeight() const = 0;

    // --- Batch render an entire draw list ---
    void Render(const ESPDrawList& list) {
        for (const auto& r : list.Rects)
            DrawRect(r.Min, r.Max, r.Color, r.Thickness, r.Filled);
        for (const auto& l : list.Lines)
            DrawLine(l.From, l.To, l.Color, l.Thickness);
        for (const auto& c : list.Circles)
            DrawCircle(c.Center, c.Radius, c.Color, c.Thickness, c.Filled);
        for (const auto& t : list.Texts)
            DrawText(t.Pos, t.Content, t.Color, t.Size, t.Centered);
        for (const auto& g : list.Gradients)
            DrawGradientRect(g.Min, g.Max, g.TopColor, g.BottomColor);
        for (const auto& rr : list.RoundedRects)
            DrawRoundedRect(rr.Min, rr.Max, rr.Color, rr.Thickness, rr.Rounding, rr.Filled);
    }
};

} // namespace KyxMarvel
